	@Test
	void retainedDomainCursorAndSnapshotSurviveAConcurrentWriterCommit() throws Exception {
		openFixture();
		List<BindingSet> expected;
		try (SailRepositoryConnection connection = repository.getConnection()) {
			expected = rows(connection);
		}
		CountDownLatch readerHasFirstRow = new CountDownLatch(1);
		CountDownLatch writerFinished = new CountDownLatch(1);
		var executor = Executors.newFixedThreadPool(2);
		try {
			var reader = executor.submit(() -> {
				try (SailRepositoryConnection connection = repository.getConnection()) {
					connection.begin(IsolationLevels.SNAPSHOT);
					List<BindingSet> observed = new ArrayList<>();
					long domains = ZeroLengthPathPlan.NODE_DOMAIN_OPENS.get();
					try (var result = connection.prepareTupleQuery(SELECT).evaluate()) {
						assertThat(result.hasNext()).isTrue();
						observed.add(result.next());
						assertThat(ZeroLengthPathPlan.NODE_DOMAIN_OPENS.get()).isGreaterThan(domains);
						readerHasFirstRow.countDown();
						assertThat(writerFinished.await(30, TimeUnit.SECONDS)).as("writer completed").isTrue();
						while (result.hasNext()) {
							observed.add(result.next());
						}
					}
					assertThat(rows(connection)).containsExactlyInAnyOrderElementsOf(expected);
					connection.rollback();
					return observed;
				} finally {
					readerHasFirstRow.countDown();
				}
			});
			var writer = executor.submit(() -> {
				try {
					assertThat(readerHasFirstRow.await(30, TimeUnit.SECONDS)).as("reader opened domain").isTrue();
					try (SailRepositoryConnection connection = repository.getConnection()) {
						var vf = connection.getValueFactory();
						connection.begin();
						connection.remove(vf.createIRI(EX + "a"), null, null);
						connection.add(vf.createIRI(EX + "new"), vf.createIRI(EX + "q"), vf.createLiteral("new leaf"));
						connection.commit();
						assertThat(count(connection)).isEqualTo(4L);
					}
					return null;
				} finally {
					writerFinished.countDown();
				}
			});
			writer.get(30, TimeUnit.SECONDS);
			assertThat(reader.get(30, TimeUnit.SECONDS)).containsExactlyInAnyOrderElementsOf(expected);
		} finally {
			executor.shutdownNow();
			assertThat(executor.awaitTermination(30, TimeUnit.SECONDS)).as("worker cleanup").isTrue();
		}
		try (SailRepositoryConnection connection = repository.getConnection()) {
			assertCountParity(connection, 4L);
		}
	}

	@Test
	void commitRollbackAndClearCannotReuseObsoleteDomains() throws Exception {
		openFixture();
		try (SailRepositoryConnection connection = repository.getConnection()) {
			var vf = connection.getValueFactory();
			var graph = vf.createIRI(EX + "graph");
			connection.begin();
			connection.add(vf.createIRI(EX + "transient"), vf.createIRI(EX + "q"), vf.createLiteral("transient"));
			assertCountParity(connection, 5L);
			connection.rollback();
			assertCountParity(connection, 3L);
			connection.begin();
			connection.add(vf.createIRI(EX + "committed"), vf.createIRI(EX + "q"), vf.createLiteral("committed"),
					graph);
			connection.commit();
			assertCountParity(connection, 5L);
			connection.clear(graph);
			assertCountParity(connection, 3L);
			connection.begin();
			connection.clear();
			assertCountParity(connection, 0L);
			connection.rollback();
			assertCountParity(connection, 3L);
			connection.clear();
			assertCountParity(connection, 0L);
			connection.add(vf.createIRI(EX + "after-clear"), vf.createIRI(EX + "q"), vf.createLiteral("after clear"));
			assertCountParity(connection, 2L);
		}
		reopenReady("spoc,posc,ospc");
		try (SailRepositoryConnection connection = repository.getConnection()) {
			long domains = ZeroLengthPathPlan.NODE_DOMAIN_OPENS.get();
			assertCountParity(connection, 2L);
			assertThat(ZeroLengthPathPlan.NODE_DOMAIN_OPENS.get()).isGreaterThan(domains);
		}
	}

