	private static void assertOpenedPolicy(boolean enabled) throws IOException {
		long a = ValueIds.createId(ValueIds.T_URI, 1L);
		long b = ValueIds.createId(ValueIds.T_URI, 2L);
		NativeLmdbQuerySource source = mock(NativeLmdbQuerySource.class);
		NativeLmdbQuerySource.NativeProbe probe = mock(NativeLmdbQuerySource.NativeProbe.class);
		when(source.hasCanonicalIds()).thenReturn(true);
		when(source.newProbe()).thenReturn(probe);
		var subjects = singletonDomain(a);
		var objects = singletonDomain(b);
		when(probe.nodeDomainIntersection(true, true)).thenReturn(subjects);
		when(probe.nodeDomainIntersection(false, false)).thenReturn(objects);
		RecordIterator statements = mock(RecordIterator.class);
		when(statements.next()).thenReturn(new long[] { a, 7L, b, 0L }, (long[]) null);
		when(probe.open(anyLong(), anyLong(), anyLong(), anyLong())).thenReturn(statements);
		var vf = SimpleValueFactory.getInstance();
		when(source.lazyValue(a, 0)).thenReturn(vf.createIRI(EX + "a"));
		when(source.lazyValue(b, 0)).thenReturn(vf.createIRI(EX + "b"));
		NativeSlotLayout layout = new NativeSlotLayout(Map.of("s", 0, "o", 1), null);
		layout.freeze(List.of("s", "o"));
		RowState row = new RowState(source, layout, EmptyBindingSet.getInstance());
		assertThat(NativeRowSeeder.seed(row.slots, layout, EmptyBindingSet.getInstance(), source)).isTrue();
		row.recomputeBoundMask();
		System.setProperty(ENABLED, Boolean.toString(enabled));
		long domains = ZeroLengthPathPlan.NODE_DOMAIN_OPENS.get();
		try (RowCursor cursor = new ZeroLengthPathPlan(0, UNKNOWN, 1, UNKNOWN, null).open(row)) {
			System.setProperty(ENABLED, Boolean.toString(!enabled));
			assertThat(cursor.next()).isTrue();
			assertThat(row.slots).containsExactly(a, a);
			assertThat(cursor.next()).isTrue();
			assertThat(row.slots).containsExactly(b, b);
			assertThat(cursor.next()).isFalse();
		}
		assertThat(row.slots).containsExactly(UNKNOWN, UNKNOWN);
		assertThat(ZeroLengthPathPlan.NODE_DOMAIN_OPENS.get() - domains).isEqualTo(enabled ? 1L : 0L);
		verify(probe).close();
		if (enabled) {
			verify(source, never()).lazyValue(anyLong(), anyInt());
		} else {
			verify(probe, never()).nodeDomainIntersection(true, true);
			verify(statements).close();
			verify(source).lazyValue(a, 0);
			verify(source).lazyValue(b, 0);
		}
	}

	private static NativeLmdbQuerySource.NodeDomainIntersection singletonDomain(long id) {
		var domain = mock(NativeLmdbQuerySource.NodeDomainIntersection.class);
		var cursor = mock(NativeLmdbQuerySource.NodeDomainIntersection.Cursor.class);
		when(domain.partitionCount()).thenReturn(1);
		when(domain.contains(id)).thenReturn(true);
		when(domain.cursor(0)).thenReturn(cursor);
		when(cursor.next()).thenReturn(true, false);
		when(cursor.nodeId()).thenReturn(id);
		return domain;
	}

	private void openFixture() throws Exception {
		openRepository("spoc,posc,ospc");
		try (SailRepositoryConnection connection = repository.getConnection()) {
			var vf = connection.getValueFactory();
			connection.begin();
			connection.add(vf.createIRI(EX + "a"), vf.createIRI(EX + "q"), vf.createIRI(EX + "b"));
			connection.add(vf.createIRI(EX + "b"), vf.createIRI(EX + "q"), vf.createLiteral("leaf"));
			connection.commit();
		}
		reopenReady("spoc,posc,ospc");
	}

	private void openRepository(String indexes) {
		store = new LmdbStore(dataDir, new LmdbStoreConfig(indexes)
				.setNativeEvaluationEnabled(true)
				.setDirectAdjacencyEnabled(true));
		repository = new SailRepository(store);
		repository.init();
	}

	private void reopenReady(String indexes) throws Exception {
		repository.shutDown();
		openRepository(indexes);
		assertThat(store.awaitDirectAdjacencyReady(60, TimeUnit.SECONDS))
				.as(store.getDirectAdjacencyReadinessDescription())
				.isTrue();
	}

	private static List<BindingSet> rows(SailRepositoryConnection connection) {
		try (var result = connection.prepareTupleQuery(SELECT).evaluate()) {
			return QueryResults.asList(result);
		}
	}

	private static long count(SailRepositoryConnection connection) {
		try (var result = connection.prepareTupleQuery(COUNT).evaluate()) {
			assertThat(result.hasNext()).isTrue();
			long count = ((Literal) result.next().getValue("n")).longValue();
			assertThat(result.hasNext()).isFalse();
			return count;
		}
	}

	private static void assertCountParity(SailRepositoryConnection connection, long expected) {
		System.setProperty(ENABLED, "false");
		assertThat(count(connection)).as("existing native producer").isEqualTo(expected);
		System.setProperty(ENABLED, "true");
		assertThat(count(connection)).as("ID-native producer").isEqualTo(expected);
	}
